        cycle = []
        visited = [[False] * len(grid[0]) for _ in range(len(grid))]

        for row in range(len(grid)):
            for col in range(len(grid[0])):
                if visited[row][col] or grid[row][col] == 'C':
                    continue

                visited[row][col] = True

                path_taken, stack = [[row, col]], [[row, col]]
                while stack:
                    next_point = stack.pop()
                    for cs in [-1, 1]:
                        nx, ny = next_point[0] + directions[0][0] * cs, next_point[1] + directions[0][1] * cs
                        if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and not visited[nx][ny] and grid[nx][ny] == 'C':
                            stack.append([nx, ny])
                            cycle.append(grid[stack[-1][0]][stack[-1][1]])

        for r, c in cycle:
            grid[r][c] = 'C'

    return [x - 1 for row in grid for x in row]

