def calculate_bus_distance(n, a, m, stops):
    q_tree = [0]
    segments = [0] * m
    for i in range(n + 1):
        if i in stops:
            segments[i] = 1
            q_tree.extend(min(range(i), key=lambda j: -a[j]))
    for j in range(1, len(q_tree)):
        q_tree[j] -= q_tree[j - 1]
    bus_segment = 0
    for i in stops:
        pre_sale = None
        seg_map = {i: 0}
        for j in range(len(q_tree)):
            if q_tree[2 * j] + q_tree[j] * 3 <= i * segments[3]:
                pre_sale = seg_map[max(0, seg_map[i] - segments[i])]
            seg_map[i] = pre_sale + segments[j]
    for i in range(m):
        for j in range(segments[i]):
            bus_segment += a[max(q_tree[j], max(seg_map[k] for k in range(i)))]

    total = 0
    for i in range(m):
        if segments[i] != 0:
            total += 1
            for j in range(segments[i]):
                total += a[max(q_tree[j], max(seg_map[k] for k in range(i)))]

    while total > 0:
        if total % 2 == 1:
            return -1
        total //= 2

    return total

