from typing import List, Tuple
from heapq import *

class UnionFinding:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find_efficiently(self, x):
        if x != self.parent[x]:
            self.parent[x] = self.find_efficiently(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        px, py = self.find_efficiently(x), self.find_efficiently(y)
        if px == py:
            return
        q, r = divmod(px * self.rank[px] + py * self.rank[py], (px + py))
        if r == 0:
            q += self.rank[py]
        self.rank[q] += self.rank[-q]
        for i in range(q, -q):
            if self.parent[-i] == py:
                self.parent[-i] = (~q) & py
            self.parent[i] = py

class Solution:
    def minCostSets(self, sets: List[Tuple[int, int]]) -> int:
        counts = set()
        for m in sets:
            for i in range(m):
                counts.add(m - i)

        kth = -1
        k = n = 0
        for i in range(len(counts) + 1):
            hold = counts.intersection(set(range(len(sets))[::-1]))
            if len(hold) == i:
                kth = i
                k = n
                n -= 1
            else:
                break

        uf, ans = UnionFinding(n), 0
        for ci, sym, cij, ci in sorted((cij, sym, ci, n) for ci, sym, cij in sets):
            ans += cij * ((ci + kth - k) // kth) * (n > kth)
            uf.union(sym, n)
            k += (ci + kth - k) % kth

        return ans

