def sort_grid(grid: List[List[int]]) -> List[Tuple[List[int], int]]:
    n, m = len(grid), len(grid[0])
    cycle = []

    # Get all cycles from the grid
    for row in grid:
        cycle.extend([[r, i] for i, cur in enumerate(row[::-1]) if i != cur])

    # Get the unique cycles
    unique_cycles = []
    for cycle in cycle:
        if cycle not in unique_cycles:
            unique_cycles.append(cycle)

    # Get the unique elements in the cycles
    unique_elements = Counter([cur[0] for cycle in unique_cycles for cur in cycle])
    for i in range(1, n - 1):
        for key, val in unique_elements.items():
            if key % (n * m) == (i + (i - 1) // (m - 1)) % (n * m):
                cycle.append((key - val * (i - 1) % (m - 1), i))
                unique_elements -= {key - val * (i - 1) % (m - 1): 1}

    # Return the result
    return unique_cycles

