class NicesSeq:
    @staticmethod
    def solve(n, s, a):
        MOD = 10**9 + 7
        acc = list(accumulate(a, initial=0))
        total_nice = 0

        for i in range(n):
            mid = max(acc[i], a[i], len(acc) - acc[-2 - i])
            total_nice += (sum(map(lambda x: len(acc) - x - a[i] - mid - mid, a)) - 1)**2 % MOD * mid % MOD

        return (accumulate(acc, initial=0) - s) % MOD if s < 0 else total_nice % MOD

