    @lru_cache(maxsize=None)
    def query(self, i, j, k):
        l = bisect_left(self.maxmax, j)
        r = bisect_right(self.maxmax, i)
        if l == r:
            return self.maxmax[l]
        minmaxer = -1
        for (blockMin, blockMax) in reversed(self.maxmax[l:r]):
            if blockMin > i or blockMax < j:
