def minimumPaintingCost(r, b, shields, constraints):
    n = len(shields)
    total_cost = 0
    colors = ['b'] * n

    # Define the cost of painting each shield
    def cost(index):
        return r if shields[index][0] > 5 else b

    # Binary search for colors
    low, high = 0, 10**(n-1)
    while low < high:
        mid = (low + high + 1) // 2
        k = (dense(mid) - dense(0)) // 2
        new_colors = colors.copy()
        for i, color in enumerate(new_colors):
            if color == 'b':
                new_colors[i] = 'r'
                total_cost += cost(n - 1 - i)
            else:
                new_colors[i] = 'b'
        gotConstraints = []
        for i, li, di in constraints:
            if i == 1:
                value = mid
                for k in range(di + 1):
                    gotConstraints.append((li, value))
                    value -= 1
            if i == 2:
                value = mid
                for k in range(di + 1):
                    gotConstraints.append((li, value))
                    value += 1
        gotConstraints.sort(key=lambda x: -x[1])
        for (li, di) in gotConstraints:
            for i, (xi, yi) in enumerate(shields):
                if xi == li:
                    if yi > 5:  # Shift if on line y = li
                        yi -= 1
                    if (yi > 1 if i%2 == 0 else yi < 10) - (xi > 5) * 2 > di or (xi < 1 if i%2 == 0 else xi > 10) - (yi > 5) * 2 > di:
                        k -= 1
                        if k == 0:
                            colors = new_colors
                            total_cost = cost(n - 1 - i)
                            break

        if k == 0:
            high -= 1
        else:
            low += 1

    if low > 10**(n-1):
        low = 1
    return total_cost, ''.join(colors)

def dense(mid):
    for i in range(mid + 1):
        y = -1 if (i % 2 == 0) - (mid + i > 0) * 2 else 0
        line = -1 if (i % 2 == 1) - (mid + i > 0) * 2 else y
        if line >= mid:
            return mid + i
    return mid
