def solve(n, sets, prices):
    if n < 0:
        return -prices[0]  # Since any k sets will have less than k distinct numbers

    min_distinct = {}
    points = []
    for c, ids in enumerate(sets):
        for i in range(1, ids + 1):
            dist = len(set(range(c, n + 1) & set(ids)))
            if dist in min_distinct:
                distinct = min_distinct[dist]
            else:
                distinct = 0
            min_distinct[dist] = distinct + 1
            if points:
                heapreplace(points, (dist + 2 * (distinct + 1), c, dist, -prices[c]))
            else:
                points.append((dist + 2 * (distinct + 1), c, dist, -prices[c]))

    heapify(points)
    ways = {0: 1}
    for _, c, dist, _ in points:
        yield ways[dist - 1 % dist]
        ways[dist - 1 % dist] = ways.get(dist - 1 % dist, 0) + ways[(dist - 1) % dist or 1]

