from collections import defaultdict
from functools import cache

def gcd(a, b):
    return (a * b) // gcd(b, a % b) if b else a

def solve(n, s, a, all_gcds):
    dp = defaultdict(int)
    total_niceness = 0

    @cache
    def helper(index=0, remaining=s):
        if index == len(a):
            total_niceness = 0
            for i, val in enumerate(a):
                if val == -1:
                    total_niceness += sum(gcd(val, num) for num in all_gcds)
            remainder, remainder_sum = divmod(remaining, n - index)
            return (remainder_sum * n + sum(gcd(val, num) for val in a for num in all_gcds)) % 1000000007, remainder
        else:
            for num in range(1, 51):
                a[index] = num
                niceness, rem = helper(index + 1, remaining - num + 1)
                dp[index, rem % (n - 1)] += niceness
            return dp[index % (n - 1), rem % (n - 1)]

    helper()
    return sum(dp.values()) % 1000000007

# Read input
T = int(input())
