    n, s = map(int, input().split())
    a = list(map(int, input().split()))
    all_gcds = [1] * 51
    for i, v in enumerate(a):
        if v != -1:
            for j in range(i + 1, n + 1):
                gcd_value = gcd(v, a[j - 1])
                all_gcds[gcd_value] *= 2
                all_gcds[gcd_value] %= 1000000007
    print(solve(n, s, a, all_gcds))
