import sys

class SegmentTree:
    def __init__(self, arr):
        self.arr = arr
        self.tree = [0] * (4 * len(arr))
        self.build(1, 0, len(arr)-1)

    def build(self, node, start, end):
        if start == end:
            self.tree[node] = self.arr[start]
        else:
            mid = (start + end) // 2
            left_node, right_node = 2 * node, 2 * node + 1

            self.build(left_node, start, mid)
            self.build(right_node, mid + 1, end)

            self.tree[node] = self.tree[left_node] + self.tree[right_node]

    def modify(self, node, start, end, index, value):
        if start == end:
            self.tree[node] += value
            return self.tree[node]
        mid = (start + end) // 2
        left_node, right_node = 2 * node, 2 * node + 1

        if index <= mid:
            self.modify(left_node, start, mid, index, value)
        else:
            self.modify(right_node, mid + 1, end, index, value)

        self.tree[node] = self.tree[left_node] + self.tree[right_node]

    def query(self, node, start, end, left, right):
        if start > right or end < left:
            return 0
        if start >= left and end <= right:
            return self.tree[node]
        mid = (start + end) // 2
        left_node, right_node = 2 * node, 2 * node + 1

        left_sum = self.query(left_node, start, mid, left, right)
        right_sum = self.query(right_node, mid + 1, end, left, right)

        return left_sum + right_sum

n, m, q = map(int, input().split())
