def count_specific_rectangles(n, m, k, table):
    def is_valid_position(x, y, width, height):
        for i in range(x, x + width):
            for j in range(y, y + height):
                if table[j][i]:
                    return False
        return True

    def dfs(x, y, current_rectangles):
        if x == n - 1 and y == m - 1:
            if current_rectangles == k:
                valid_rectangles_count += 1
            return

        if x == n or y == m or current_rectangles > k:
            return

        for new_x in range(x, n):
            for new_y in range(y, m):
                if table[new_y][new_x] == '0':
                    new_width = new_y - y + 1
                    new_height = new_x - x + 1
                    if is_valid_position(x, y, new_width, new_height):
                        dfs(new_x + 1, y + 1, current_rectangles + 1)

    table = [list(row) for row in table]
    valid_rectangles_count = 0
    dfs(0, 0, 0)
    return valid_rectangles_count

