def gcd_of_pairs(numbers):
    gcd_sum = 0
    for i in range(len(numbers)):
        for j in range(i+1, len(numbers)):
            gcd = 0
            for k in range(2, max(numbers[i], numbers[j]) + 1):
                if numbers[i] % k == 0 and numbers[j] % k == 0:
                    gcd = k
            gcd_sum += gcd
            gcd_sum %= 1000000007
    return gcd_sum

T = int(input())
