    if -1 in numbers:
        nice_sum = 0
        for i in range(N):
            number_required = S // (i + 1)
            for j in range(i + 1, N + 1):
                if numbers[j - 1] < number_required:
                    numbers[j - 1] += number_required
                    nice_sum += numbers[j - 1]
                    break
        nice_sum %= 1000000007
    else:
        nice_sum = 0
    nice_sum = gcd_of_pairs(numbers)
    print(int(nice_sum % 1000000007))
