from collections import defaultdict, deque
from typing import List

def read_input():
    n, m = map(int, input().split())
    grid = [list(map(int, input().split())) for _ in range(n)]
    return n, m, grid

def create_graph(grid):
    graph = defaultdict(lambda: deque())
    for i in range(n):
        for j in range(m):
            value = grid[i][j]
            for y in range(1, 1+m):
                x = (value // (y-1)) + (value % (y-1))
                graph[i, j].append(x)
    return graph

def bfs(graph, start):
    visited = {start}
    queue = deque([start])
    out = [start]
    while queue:
        v = queue.popleft()
        for neighbor in graph[v]:
            if neighbor not in visited:
                visited.add(neighbor)
                out.append(neighbor)
                queue.append(neighbor)

    return out[1:]

def reduce_swap_operations(graph):
    cycles = []
    while True:
        for v1, edge in graph.items():
            for y in range(1, 1 + m):
                x_close = v1[0], (y-1) * m  + v1[1]
                for y_edge in filter(lambda x: min(x) == y,
                                     edge):
                    if x_close == (y, x_close[1]):
                        out = bfs(graph, y_edge)
                        cycle = [(y, x[1]) for y, x in zip(range(y_edge, x_edge), out)]
                        if cycle not in cycles:
                            cycles.append(cycle)
    return cycles[-1]

def print_result(n, m, cycles):
    sum_length = 0
    for cycle in cycles:
        print(f"{len(cycle)} {" ".join(map(str, cycle))}") 
