import sys

def lexicographically_changing_string(s):
    n = len(s) + 1
    dp = ["inf"] * n
    prefix = s[::-1]  # Reverse the string to facilitate lexicographic comparison

    for i in range(n - 1, -1, -1):
        for j in range(i):
            if s[i] == prefix[j]:
                dp[i] = min(dp[i], dp[j] + 1)
        if s[i] != prefix[n - i - 1]:
            dp[i] = 0
    lcs = max(dp)
    for i in range(n - lcs):
        if s[i] != prefix[-i - 1]:
            lcs = n - 1 - i - 1

    return dp, lcs

